function rle_1(str) {
  if (str.length === 0) return [];
  let result = [];
  let currentChar = str[0];
  let count = 1;
  for (let i = 1; i < str.length; i++) {
    if (str[i] === currentChar) {
      count++;
    } else {
      result.push({ char: currentChar, count: count });
      currentChar = str[i];
      count = 1;
    }
  }
  result.push({ char: currentChar, count: count });
  return result;
}
```

